pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 2 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        vm.roll(1);
        bytes32 guessHash = blockhash(1);
        c.lockInGuess{value: 1 ether}(guessHash);

        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
